using NUnit.Framework;using SqlSchemaCompare.Core.Comparers;using SqlSchemaCompare.Core.Models;using SqlSchemaCompare.Core.ScriptGeneration;
namespace SqlSchemaCompare.Tests; public class SchemaTests{static ColumnSchema C(string n,string t="nvarchar",int l=100,bool nul=true)=>new("dbo","Users",n,t,l,null,null,nul,false,null,null);static DatabaseSchema Db(params ColumnSchema[] c)=>new([new TableSchema("dbo","Users",c,[])],[],[]);[Test]public void SameColumns_NoDifference()=>Assert.That(new SchemaComparer().Compare(Db(C("Name")),Db(C("Name"))),Is.Empty);[Test]public void MissingSourceColumn_IsAdded()=>Assert.That(new SchemaComparer().Compare(Db(C("Name"),C("Email")),Db(C("Name"))),Has.One.Matches<SchemaDifference>(x=>x.DifferenceType==DifferenceType.Added));[Test]public void DifferentType_IsModified()=>Assert.That(new SchemaComparer().Compare(Db(C("Name","nvarchar")),Db(C("Name","int"))),Has.One.Matches<SchemaDifference>(x=>x.DifferenceType==DifferenceType.Modified));[Test]public void TargetOnlyTable_DoesNotDrop(){var d=new SchemaComparer().Compare(Db(),new DatabaseSchema([new TableSchema("dbo","Old",[],[])],[],[]));var sql=new SqlScriptGenerator().Generate(d,"S","T");Assert.That(sql,Does.Not.Contain("DROP TABLE"));}}
